    }

    // 4. Residual Variance Smoothing:
    // Stricter penalty for deviation from mean to force uniform compaction.
    if post_residual > 2 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 1.65;
    }

    // 5. Residual Quantization & Parity:
    // Bias towards multiples of 5, and parity reward for even residuals.
    let rem5 = post_residual % 5;
    score += (rem5 as f64) * 2.8;
    if post_residual % 2 == 0 { score -= 1.8; }

    // 6. Aggressive Tail-End Compaction:
    // Higher penalty for opening new bins near the end of the stream.
    if progress > 0.70 {
        score += post_residual as f64 * 9.5;
        if bin_residual == bin_capacity {
            score += 450.0 * (1.0 + progress); 
        }
    }

    // 7. Small-Item Buffering:
    // Penalty for creating a bin that is too small for the next item, 
    // especially as the stream progresses.
