        score -= 30.0;
    }

    // 3. Global State Balancing: If we have many open bins, we should be more 
    // aggressive in closing them (prioritizing bins with lower post_residual).
    // If we have few bins, we can afford to be more selective.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 0.5;
    }

    // 4. New Bin Logic: If bin_residual == bin_capacity, this is a "new bin" candidate.
    // We only want to open a new bin if the current best-fit options are very poor.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high to encourage packing into existing ones.
