    let post = post_residual as f64;

    // Base cost: Best-Fit Decreasing logic, favoring tight fills (lower post_residual).
    // We penalize larger post_residual quadratically to avoid fragmentation.
    let mut score = post * post / 100.0;

    // Lookahead logic: if next_item_size is large, we want to reserve space in open bins.
    // If post_residual is smaller than the next item, we create "dead space" that cannot be filled.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Dynamic pressure: As the stream progresses, become more conservative about opening new bins.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is already very tight,
        // or if we have very few fitting bins left.
        let openness_penalty = 50.0 * (1.0 - progress);
        let fitting_pressure = if fitting_bins_count > 0 { 40.0 } else { 0.0 };
        score += openness_penalty + fitting_pressure;
    } else {
        // If we are placing in an existing bin, reward bins that are closer to the mean_residual
        // to keep the distribution of remaining spaces uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // Penalize fragmentation when the bin is nearly full but not empty (the "difficult" range 1-10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation).
    // If post_residual is in (0, 10), it's likely "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead Logic: If a next item exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for keeping space for the next item
            score -= 30.0;
        } else {
            // Penalty for stranding the next item if this bin was our best chance
            if fitting_bins_count == 1 {
                score += 20.0;
            }
        }
    }

    // 3. Harmonic Class Logic: Prefer filling bins to specific "harmonic" thresholds (e.g., 50, 33, 25).
    // We normalize the post_residual to favor bins that leave "clean" fractions.
    let harmonic_fit = (post_residual % 25) as f64;
    score += harmonic_fit * 0.5;

    // 4. Global State Awareness:
    // As the stream progresses, become more aggressive in packing (decreasing tolerance for new bins).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High cost to open a new bin, which scales with the number of already open bins.
        // We make it increasingly harder to open a new bin as the stream goes on.
        score += 35.0 + (open_bins_count as f64 * 2.0) + (progress * 20.0);
    }

    // 5. Residual Balancing:
    // Avoid creating bins that are significantly below the mean residual of current bins.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit future items.
    // Small gaps (1-9) are usually "dead" because the minimum item size is 1.
    // We penalize these heavily to force tighter packing into larger gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0 / (post_residual as f64);
    }

    // 2. Lookahead Integration: If the next item can fit in the current post_residual,
    // we reward this placement to keep the bin useful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If the bin is new, we add a penalty proportional to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.5);
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item,
    // we lower the score to ensure we don't accidentally prefer a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Mean Residual Balancing: Prefer bins closer to the global mean to maintain uniformity.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

