        } else {
            // Penalize bin that makes the next item impossible to fit
            score += 20.0;
        }
    }

    // 3. Statistical balance: Discourage creating residuals far below the current mean
    // This maintains "tightness" across the active set
    let deviation = (post_residual as f64 - mean_residual).abs();
    if post_residual < (mean_residual * 0.5) as u32 {
        score += deviation * 0.5;
    }

    // 4. Fitting constraints: If this is the last chance for this item, prioritize lower post_residual
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression: As the stream nears the end, prioritize closing bins (Best Fit)
