    // If post_residual is > 0 and < 10, it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item fits into the post_residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic threshold for opening new bins. 
    // If this is a new bin (bin_residual == bin_capacity):
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is very tight or we have many open bins.
        // As we approach the end of the stream, be more conservative about opening new bins.
        let openness_penalty = (open_bins_count as f64) * 2.0;
        let final_phase_penalty = (1.0 - progress) * 15.0;
        score += 45.0 + openness_penalty + final_phase_penalty;
    } else {
        // If it's an existing bin, favor bins that keep the mean residual balanced.
        // If the bin is "too empty" compared to the mean, we might want to fill it more.
        let residual_diff = (bin_residual as f64) - mean_residual;
        score += residual_diff * 0.1;
    }

    // If this is the only bin that can fit the item, give it a strong preference 
    // to avoid unnecessary bin creation, unless the fit is extremely poor.
    if fitting_bins_count == 1 && post_residual < 20 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow more flexibility as the stream ends
    let new_bin_penalty = if is_new_bin {
        25.0 * (1.0 - progress).powf(0.5) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Calculate base score: favor smaller post_residual (Best Fit principle)
    // We penalize very small residuals that are likely to become "dead space" 
    // unless they are zero (perfect fit).
    let mut score = post_residual as f64;

    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item is large, avoid leaving tiny gaps
    if next_item_size > 0 {
        let gap_waste = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += gap_waste * 0.2;
    }

    // Interaction with mean_residual: avoid bins that deviate significantly from average,
    // as we want to keep space utilization uniform across bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Last chance logic: if this is the only bin that fits the current item, 
    // strongly incentivize picking it to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
