    // that creates residual space incapable of holding the lookahead item.

    let mut score = post_residual as f64;

    // 1. If this is a new bin (bin_residual == bin_capacity), only open it if
    // no existing bin provides a "near-perfect" fit.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless existing options are terrible.
        score += 45.0;

        // If the item is large, opening a new bin is slightly less penalized.
        score -= (item_size as f64) * 0.2;
        return score;
    }

    // 2. Harmonic Penalty: Penalize residuals that are small but unusable.
    // If post_residual is in the range [1, 9], it's dangerous because min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 2.0);
    }

    // 3. Lookahead Alignment: If the post_residual cannot fit the next item, 
    // add a penalty. If it can, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (synergy).
            score -= 15.0;
        } else {
            // Penalize bins that "strand" the next item.
            score += 10.0;
        }
    }

    // 4. Density Balancing: If we have many open bins, prioritize filling the 
    // one with the smallest residual (Best Fit) to keep the packing tight.
    score += (bin_residual as f64) * 0.1;

    // 5. Progression modifier: As we reach the end of the stream, 
    // become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
