    let is_new_bin = bin_residual == bin_capacity;

    // Start with a base score weighted by post_residual to favor tight fits.
    // We use a non-linear scaling to penalize larger gaps more aggressively.
    let mut score = (post_residual as f64).powf(1.15);

    // 1. Fragmentation Avoidance:
    // Small residuals (1-12) are "dead zones". Penalize heavily to force better packing.
    if post_residual > 0 && post_residual < 13 {
        score += 85.0 * (1.0 - progress * 0.2);
    }

    // 2. Lookahead Synergy:
    // If the next item fits, prioritize the bin that leaves the least "wasted" space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let space_after_next = (post_residual - next_item_size) as f64;
            score -= 95.0 * (1.0 - (space_after_next / bin_capacity as f64));
        } else if fitting_bins_count > 0 {
            // If next item doesn't fit, penalize this bin to keep it for larger items.
            score += 45.0 * (1.0 - progress);
        }
    }

    // 3. Dynamic Bin Opening Logic:
    // Higher penalty for new bins as the stream progresses to force consolidation.
    if is_new_bin {
        let base_cost = 110.0;
        let density_pressure = (open_bins_count as f64 * 3.5) + (progress * 80.0);
        let efficiency_penalty = mean_residual * 1.5;
        score = base_cost + density_pressure + efficiency_penalty;
    }

    // 4. Mean Residual Smoothing:
    // Penalize bins that deviate from the current mean residual to keep bins balanced.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.8;

    // 5. Parity Bias:
    // Bias towards residuals that are multiples of 4 (common sub-multiples of 100).
    score += ((post_residual % 4) as f64) * 2.0;

    // 6. Tail-End Compaction:
    // As the stream nears completion, become extremely conservative with new bins.
    if progress > 0.85 {
        score += (post_residual as f64) * 5.0;
        if is_new_bin {
            score += 300.0;
        }
    }

    // 7. Capacity Utilization:
    // If we are filling a bin to near-full, reward it to finalize that bin.
    if post_residual < 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

