pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual).
    // We use a quadratic penalty for post_residual to favor Best-Fit behavior.
    let mut score = post * post * 0.01;

    // Lookahead logic: If the next item fits into the current post_residual, 
    // heavily reward this bin to minimize future bin openings.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 5.0;
    }

    // Dynamic constraint: Penalize opening a new bin (bin_residual == bin_capacity)
    // based on the progress of the stream. As the stream ends, we become more
    // conservative about opening new bins.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with progress to force consolidation
        // in the later stages of the stream.
        score += 25.0 * (1.0 + progress * 2.0);
    }

    // Adaptive Penalty: If there are very few fitting bins, avoid "wasting" this bin
    // on a poor fit if it's the only one left.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 15.0 * (1.0 - progress);
    }

    // Mean-balancing: Penalize bins that deviate significantly from the mean_residual
    // to keep the fill-levels of active bins relatively uniform.
    let deviation = (post as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Adaptive Residual Thresholding
    // Penalize "dead-zone" fragmentation (5-18 range) more aggressively to force tighter fits.
    if post_residual > 4 && post_residual < 19 {
        score += 88.0 * (1.0 - (progress * 0.15));
    }

    // 2. Lookahead Synergy with Non-Linear Tightness
    // Shifted focus to prioritize bins that can accommodate the next item while minimizing wasted residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let space_after_next = (post_residual - next_item_size) as f64;
            // Reward bins that leave exactly 0 or multiples of 10 to increase future compatibility
            let alignment_bonus = if space_after_next % 10.0 == 0.0 { 15.0 } else { 0.0 };
            score -= (95.0 - (space_after_next * 0.8)) + alignment_bonus;
        } else if fitting_bins_count < 3 {
            score -= 75.0 * (1.0 - progress * 0.2);
        }
    }

    // 3. Dynamic Bin Opening Cost
    // Penalize new bin opening based on current packing density
    if bin_residual == bin_capacity {
        let density_factor = (open_bins_count as f64 / (total_items as f64 / 15.0)).clamp(0.5, 2.5);
        let base_cost = 110.0 * density_factor;
        score += base_cost + (mean_residual * 1.8);
    }

    // 4. Variance Smoothing
    // Penalize bins that deviate from the current mean_residual, but allow more slack early in the stream.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * (1.2 - (progress * 0.4));

    // 5. Parity & Granularity
    // Bias towards leaving residuals that are divisible by 4 (common factor for 20, 25, 50, 100 capacities).
    let parity_penalty = (post_residual % 4) as f64 * 3.5;
    score += parity_penalty;

    // 6. Aggressive Tail-End Compaction
    // Tighten constraints on open bins significantly after 85% progress.
    if progress > 0.85 {
        score += post_residual as f64 * 6.5;
        if bin_residual == bin_capacity {
            score += 350.0; 
        }
    }

    // 7. Small-Item Protection
    // Specifically protect small bins (residual < 10) from being chosen if we expect a larger item next.
    if post_residual < 10 && next_item_size > post_residual {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones": residuals between 1 and 9 are often unusable for future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Alignment: Favor bins where the post_residual is a multiple of common item sizes (e.g., 20, 25, 33).
    // This helps maintain "packability" for the remaining space.
    let harmonic_penalty = if post_residual % 20 == 0 { -10.0 } else if post_residual % 25 == 0 { -8.0 } else { 0.0 };
    score += harmonic_penalty;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it leaves a "clean" remainder (0 or >= 10)
        if post_residual - next_item_size == 0 {
            score -= 20.0;
        }
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless the current best fit is objectively terrible.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high, scaled by how many bins are already open.
        score += 45.0 + (open_bins_count as f64 * 0.5);

        // If we have many bins, be even more conservative about opening a new one.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // 5. Progression Scaling: As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    // 6. Mean Residual Balancing: If this bin's residual is significantly lower than the mean, 
    // it's a "tight" bin. We want to pack it to keep the average high enough to fit future items.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Adaptive Residual Thresholding
    // Penalize "near-miss" fragmentation more aggressively to favor tight fits.
    if post_residual > 0 && post_residual < 24 {
        score += 82.0 * (1.2 - (progress * 0.25));
    }

    // 2. Lookahead Synergy & Entropy Management
    // Non-linear decay on next_item_size fit to prevent wasting space for small items.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 92.0 * (1.0 - tightness.powf(0.6));
        } else if fitting_bins_count < 3 {
            score -= 75.0 * (1.0 - progress * 0.4);
        }
    }

    // 3. Dynamic Bin Opening Cost (The "New Bin" Gate)
    // Shift the cost to be more conservative mid-stream and highly restrictive late-stream.
    if bin_residual == bin_capacity {
        let base_cost = 105.0;
        let density_pressure = (open_bins_count as f64 * 3.2) + (progress * 85.0);
        let efficiency_penalty = mean_residual * 1.45;
        score += base_cost + density_pressure + efficiency_penalty;
    }

    // 4. Residual Variance Smoothing (Gaussian-like penalty)
    // Penalize deviation from the current average to maintain uniform bin states.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 1.15;

    // 5. Parity & Modulo Optimization
    // Bias toward multiples of 4 and 5; 4 is common in bin packing distributions, 5 is a standard divisor.
    let rem = post_residual % 4;
    score += (rem as f64) * 2.1;

    // 6. Aggressive Tail-End Compaction
    // Exponential increase in penalty for new bins as the stream approaches completion.
    if progress > 0.85 {
        score += post_residual as f64 * 6.5;
        if bin_residual == bin_capacity {
            score += 450.0 * progress;
        }
    }

    // 7. Small-Item Stranding Protection
    // Penalize bins that leave behind a "useless" residual smaller than the next likely arrival.
    if post_residual < next_item_size && post_residual > 0 {
        let stranding_penalty = 45.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        score += stranding_penalty;
    }

    // 8. Global Density Correction
    // Penalize the bin if it significantly drops the global efficiency (mean_residual).
    if post_residual > (mean_residual * 1.5) as u32 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
