    }

    // 4. Residual Variance Smoothing:
    // Penalize large deviations from mean_residual, but normalize by bin capacity.
    if post_residual > 6 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 1.15;
    }

    // 5. Residual Quantization & Parity:
    // Bias towards leaving residuals that are multiples of 4 or 5.
    let rem = post_residual % 4;
