    // Penalize deviation to prevent hoarding of space, but allow wider variance for larger items.
    if post_residual > 12 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 1.15;
    }

    // 5. Residual Quantization & Parity:
    // Bias towards leaving residuals that are multiples of 4 or 8 (common sub-multiples of 100).
    let rem_parity = (post_residual % 4) as f64;
    score += rem_parity * 2.2;

    // 6. Aggressive Tail-End Compaction:
    // Forced closure of bins as we reach the end of the stream.
    if progress > 0.88 {
        score += post_residual as f64 * 6.5;
        if bin_residual == bin_capacity {
            score += 320.0;
        }
    }

    // 7. Small-Item Buffering & Dead Space Avoidance:
    // Avoid leaving "unusable" space that is strictly smaller than the average incoming item.
    if post_residual > 0 && post_residual < 6 {
        score += 45.0;
    }

    // 8. Density-Based Bias:
    // Slightly favor bins that are already more filled to consolidate space.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
