    // New Bin Penalty: Heavily penalize opening a new bin unless forced.
    // We scale this penalty by the number of open bins to encourage consolidation.
    if is_new_bin {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // If this is the only bin that fits, we should prioritize it significantly 
    // to avoid the new-bin penalty.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Non-linear coupling: As we progress through the stream, become more 
    // conservative about leaving large residuals.
    score += (bin_capacity - post_residual) as f64 * progress * 0.5;

    // Penalize bins that deviate far from the mean_residual to keep bin fullness balanced
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
