    // 4. Residual Variance Smoothing:
    // Penalize large deviations from mean_residual to prevent "bin-hoarding" of empty space.
    if post_residual > 5 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 1.2;
    }

    // 5. Residual Quantization & Parity:
    // Bias towards leaving residuals that are multiples of 4 or 5 (common item size triggers).
    let rem = post_residual % 5;
    score += (rem as f64) * 2.2;

    // 6. Aggressive Tail-End Compaction:
    // Force tighter packing as we reach the end of the stream to reduce final bin overhead.
    if progress > 0.85 {
        score += post_residual as f64 * 6.5;
