    } else {
        // 4. Residual Variance Smoothing:
        // Penalize bins that drift too far from the mean_residual to keep space uniformly available.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.85;
    }

    // 5. Parity & Quantization:
    // Items often come in clusters; favoring multiples of 4 helps alignment.
    score += (post_residual % 4) as f64 * 2.0;

    // 6. Tail-End Compaction:
    // As the stream finishes, the cost of opening a new bin should be prohibitively high.
    if progress > 0.85 {
