    // 2. Lookahead logic: If the next item is large, prioritize keeping space.
    // If the next item cannot fit in this bin's post_residual, we penalize it 
    // to encourage choosing a bin where the next item *could* fit.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that can accommodate both current and next item
            score -= 5.0;
        }
    }

    // 3. Global state: If many bins are open, try to consolidate by 
    // preferring bins that already have a lower residual (filling them up).
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    // 4. New Bin Logic: Discourage opening a new bin unless the fit is perfect (e.g., 0 residual)
    // or if the current bins are all quite full (poor mean_residual).
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score -= 10.0; // Perfect fit in new bin is good
        } else {
            // Heavily penalize opening a new bin if we have fitting options
            score += 40.0 + (mean_residual * 0.5);
        }
    }

    // 5. Prefer bins that are already "tight" to minimize the number of active bins
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

