    if post_residual % 2 == 0 { score -= 2.2; }

    // 6. Aggressive Tail-End Compaction:
    // Exponentially increase penalty for new bins as we reach the end of the stream.
    if progress > 0.75 {
        score += post_residual as f64 * 12.0;
        if bin_residual == bin_capacity {
