            // Reward bins that leave space for the next item
            score -= 5.0;
        }
    }

    // 4. Fitting Constraint: If this is the last chance for the current item, 
    // reduce the penalty for a new bin to prevent forcing an extremely tight,
    // inefficient fit into an existing bin that leaves a "dead" residual.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
