            score += (25.0 - post_residual as f64) * 3.5;
        }
    }

    // 2. Lookahead Synergy (Refined)
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 145.0 * (1.1 - tightness.powf(0.35));
    }

    // 3. Dynamic Bin Opening Cost (Strictly tuned for high-density)
    if bin_residual == bin_capacity {
        // Higher base penalty to force better utilization of existing bins
        let base_cost = 145.0;
        let density_pressure = (open_bins_count as f64 * 5.5) + (progress * 95.0);
        let efficiency_penalty = mean_residual * 2.1;
        score += base_cost + density_pressure + efficiency_penalty;
    } else {
        // Reward existing bins that are "active" (fitting items well)
        let utilization = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= utilization * 25.0;
    }

    // 4. Residual Variance Smoothing
    // Penalize deviation from the global mean to promote homogenization
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 1.85;

    // 5. Quantization Bias
    // Favor residuals that are multiples of 4 (common sub-sizes)
    let rem4 = post_residual % 4;
    score += (rem4 as f64) * 3.2;

    // 6. Tail-End Compaction
    if progress > 0.85 {
        score += post_residual as f64 * 14.0;
        if bin_residual == bin_capacity {
            score += 600.0; 
        }
    }

    // 7. Global Density Incentive
    // Exponentially reward density as we fill up.
    if open_bins_count > 0 {
        let density_factor = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= density_factor * 40.0 * (1.0 + progress);
    }

    // 8. Fitting Bin Pressure
    // If we have very few bins that can fit the item, prioritize the most efficient one.
    if fitting_bins_count < 4 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
