    // 5. Residual Quantization & Parity:
    // Bias towards multiples of 5, and parity reward for even residuals to encourage fit-chaining.
    let rem5 = post_residual % 5;
    score += (rem5 as f64) * 3.2;
    if post_residual % 2 == 0 { score -= 2.2; }

    // 6. Aggressive Tail-End Compaction:
    // Significantly increased penalty for opening new bins as the stream nears exhaustion.
    if progress > 0.75 {
        score += post_residual as f64 * 11.0;
        if bin_residual == bin_capacity {
            score += 550.0 * (1.0 + progress); 
        }
    }

    // 7. Small-Item Buffering:
    // Penalty for creating a bin that becomes "useless" (cannot fit next item) 
    // when it could have been avoided.
    if post_residual < next_item_size && post_residual > 0 {
        score += 75.0 * (1.0 + progress * 0.6);
