        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 1.85;
    }

    // 5. Residual Quantization & Parity:
    // Bias towards multiples of 5, and heavily reward even residuals for better alignment.
    let rem5 = post_residual % 5;
    score += (rem5 as f64) * 3.2;
    if post_residual % 2 == 0 { score -= 2.5; }

    // 6. Aggressive Tail-End Compaction:
    // Near the end, the cost of an empty bin is catastrophic.
    if progress > 0.85 {
        score += post_residual as f64 * 12.0;
        if bin_residual == bin_capacity {
            score += 600.0 * (1.0 + progress); 
        }
    }

    // 7. Small-Item Buffering & Lookahead:
    // If we create a bin that can't fit the next item, we penalize it based on remaining capacity.
    if post_residual < next_item_size && post_residual > 0 {
        score += 85.0 * (1.0 + progress * 0.5);
    }

