    // Heuristic Strategy: Best-Fit Decreasing variant with a penalty for creating small, unusable residuals
    // (the "fragmentation trap") and a lookahead bias to save space for future, potentially larger items.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Fragmentation Penalty: Penalize residuals that are too small to fit the smallest possible items (10).
    // If post_residual is in (0, 10), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Integration: If next_item_size exists, penalize bins that can't fit it.
    // This encourages grouping items that complement each other.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - progress);
    }

    // 3. Global State Balancing: If we have many open bins, penalize opening a new one unless the fit is very good.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is scaled by the number of currently open bins
        // and the density of the existing bins (mean_residual).
        score += 40.0 + (open_bins_count as f64 * 0.5) - (mean_residual * 0.2);
    }

    // 4. Criticality Adjustment: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Dynamic Thresholding: As we approach the end of the stream, prioritize packing density over future flexibility.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Refined Fragmentation Penalty:
    // Strengthened to penalize "unusable" small gaps more aggressively early on.
    if post_residual > 0 && post_residual < 24 {
        score += 98.0 * (1.25 - (progress * 0.25));
    }

    // 2. Lookahead Synergy:
    // Increased weight on next_item_size fitting. If we cannot fit the next item, 
    // we penalize based on bin count to force consolidation.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 135.0 * (1.0 - tightness.powf(0.35));
        } else if fitting_bins_count < 10 {
            score -= 95.0 * (1.0 - progress * 0.25);
        }
    }

    // 3. Dynamic Bin Opening Cost:
    // Increased base cost to heavily discourage opening new bins.
    if bin_residual == bin_capacity {
        let base_cost = 135.0;
        let density_pressure = (open_bins_count as f64 * 5.2) + (progress * 95.0);
        let efficiency_penalty = mean_residual * 1.85;
        score += base_cost + density_pressure + efficiency_penalty;
    } else {
        // Target dynamic mean residual to keep bin fill levels consistent.
        let target_res = mean_residual.max(22.0);
        score -= (1.0 - (post_residual as f64 / target_res).min(1.0)) * 12.0;
    }

    // 4. Residual Variance Smoothing:
    // Penalty for deviation from the mean to force uniform compaction across all bins.
    if post_residual > 4 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 1.95;
    }

    // 5. Residual Quantization & Parity:
    // Bias towards multiples of 5; added secondary parity bias for even residuals.
    let rem5 = post_residual % 5;
    score += (rem5 as f64) * 3.2;
    if post_residual % 2 == 0 { score -= 2.5; }

    // 6. Aggressive Tail-End Compaction:
    // Significantly steeper penalty for opening bins when the stream is near exhaustion.
    if progress > 0.65 {
        score += post_residual as f64 * 12.0;
        if bin_residual == bin_capacity {
            score += 550.0 * (1.0 + progress); 
        }
    }

    // 7. Small-Item Buffering:
    // Stronger penalty for creating a bin that is too small for the next item, 
    // discouraging fragmented packing.
    if post_residual < next_item_size && post_residual > 0 {
        score += 75.0 * (1.0 + progress * 0.9);
    }

    // 8. Global Density Incentive:
    // Reward high utilization bins to prevent "bin sprawl".
    if open_bins_count > 8 {
        score -= (bin_capacity - post_residual) as f64 * 0.22;
    }

    score
}

