    let progress = step_index as f64 / total_items as f64;

    // 1. Refined Fragmentation Penalty:
    // Increased weight on mid-range residual waste to prevent "hollow" bins.
    if post_residual > 0 && post_residual < 25 {
        score += 105.0 * (1.15 - (progress * 0.15));
    }

    // 2. Lookahead Synergy:
    // Optimize for the next item's fit, but apply a non-linear penalty for "over-tightness"
    // that might leave an unusable sliver of space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 135.0 * (1.0 - tightness.powf(0.35));
            if post_residual - next_item_size < 3 {
                score -= 25.0; // Bonus for near-perfect consolidation
            }
        } else if fitting_bins_count < 6 {
            score -= 95.0 * (1.0 - progress * 0.25);
        }
    }

    // 3. Dynamic Bin Opening Cost:
    // Heavier penalty for opening new bins relative to the current density.
    if bin_residual == bin_capacity {
        let base_cost = 145.0;
        let density_pressure = (open_bins_count as f64 * 5.2) + (progress * 95.0);
        let efficiency_penalty = mean_residual * 1.85;
        score += base_cost + density_pressure + efficiency_penalty;
    } else {
        // Favor bins that align with the current mean to maintain high-density clusters.
        let target_res = mean_residual.clamp(12.0, 24.0);
        score -= (1.0 - (post_residual as f64 - target_res).abs() / bin_capacity as f64) * 15.0;
    }

    // 4. Residual Variance Smoothing:
    // Stricter penalty for deviation from mean to force uniform compaction.
    if post_residual > 2 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 1.85;
    }

    // 5. Residual Quantization & Parity:
    // Reward residuals divisible by 4 or 5 as they offer better combinatorial flexibility.
    if post_residual % 4 == 0 { score -= 4.5; }
    else if post_residual % 5 == 0 { score -= 3.5; }

    // 6. Aggressive Tail-End Compaction:
    // Exponentially increase penalty for new bins as the stream nears exhaustion.
    if progress > 0.85 {
        score += post_residual as f64 * 12.0;
        if bin_residual == bin_capacity {
            score += 600.0 * (1.0 + progress); 
        }
    }

    // 7. Small-Item Buffering:
    // Penalize creating bins that are effectively "locked" for the next item.
    if post_residual < next_item_size && post_residual > 0 {
        score += 75.0 * (1.0 + progress * 0.5);
    }

    // 8. Global Density Incentive:
    // Reward high-utilization bins more strongly when many bins are already open.
    if open_bins_count > 8 {
        score -= (bin_capacity - post_residual) as f64 * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit typical items, 
    // it creates "splinters" (dead space). Penalize residuals < 10 (assuming min item size is ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open Bins Pressure: Penalize opening new bins, but allow it if the current 
    // fit is extremely poor (Best Fit Decreasing logic).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for opening a new bin, scaling with how many bins are already open.
        score += 40.0 + (open_bins_count as f64 * 2.5);
    } else {
        // Reward filling bins that are already tight (Best Fit).
        score -= (bin_capacity - bin_residual) as f64 * 0.5;
    }

    // 3. Lookahead Synergy: If the next item can fit in the current post_residual,
    // prioritize this bin to reduce fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Mean Residual Balancing: Avoid spreading items too thin.
    // If this bin's residual is significantly better than the mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it 
    // heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    score
}

