    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 1.85;

    // 5. Residual Quantization & Parity:
    // Bias towards multiples of 5, but use a softer parity reward.
    score += (post_residual % 5) as f64 * 3.2;
    if post_residual % 2 == 0 { score -= 2.2; }

    // 6. Aggressive Tail-End Compaction:
    // Exponentially increase penalty for new bin creation as stream concludes.
    if progress > 0.65 {
