        if is_new_bin {
            score += 550.0 * (1.0 + progress); 
        }
    }

    // 7. Small-Item Buffering & Capacity Check:
    // Strongly penalize small post-residuals that cannot hold a "typical" future item.
    if post_residual < next_item_size && post_residual > 0 {
        score += 75.0 * (1.0 + progress * 0.9);
