pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prefer tighter fits (lower post_residual).
    let mut score = post;

    // 1. Fragmentation Penalty:
    // Increased weight to avoid creating "dead" space that cannot accommodate future items.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post) * 12.0 * (1.0 + progress);
    }

    // 2. Lookahead Synergy:
    // If next item fits well, prioritize the bin to create a "perfect" sequence.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let space_after_next = (post_residual - next_item_size) as f64;
            // Reward bins that leave exactly enough room for the next item or very little waste.
            score -= (1.0 / (1.0 + space_after_next)) * 150.0;
        } else {
            // If next item doesn't fit, penalize this bin slightly unless it's the only option.
            if fitting_bins_count > 1 {
                score += 25.0 * (1.0 - progress);
            }
        }
    }

    // 3. Dynamic Bin Opening Cost:
    // Heavily penalize opening new bins, scaling with progress and current system density.
    if bin_residual == bin_capacity {
        let base_cost = 135.0;
        let density_penalty = (open_bins_count as f64 * 3.5) + (progress * 120.0);
        let efficiency_penalty = mean_residual * 2.2;
        score += base_cost + density_penalty + efficiency_penalty;
    } else {
        // Encourage using existing bins that keep residuals near the global mean.
        let dev = (post - mean_residual).abs();
        score += dev * 0.8;
    }

    // 4. Global Density Incentive:
    // If we have many open bins, prioritize those that are nearly full to consolidate.
    if open_bins_count > 12 {
        score -= (bin_capacity - post_residual) as f64 * 0.25;
    }

    // 5. Tail-End Compaction:
    // As stream ends, the cost of opening a new bin is prohibitive.
    if progress > 0.85 {
        if bin_residual == bin_capacity {
            score += 600.0;
        }
        score += post * 15.0;
    }

    // 6. Parity and Quantization Bias:
    // Slight preference for even residuals to prevent odd-number-locked fragmentation.
    if post_residual % 2 == 0 {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "slivers" (dead space too small for common items)
    // If post_residual is < 10, it's likely wasted space unless it's 0.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Heuristic: Best-Fit Decreasing logic (favor small post_residual)
    // We reward bins that leave exactly 0 space (perfect fit).
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead logic: If we have a next item, check if it fits in the current post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for "pairing" items (Best-Fit-Pairing)
            score -= 30.0 * (1.0 - progress);
        } else if post_residual < 20 && next_item_size > post_residual {
            // Penalty if we leave space that can't fit the next item effectively
            score += 15.0;
        }
    }

    // Global state: If we have many bins open, be more aggressive about filling them
    // rather than opening new ones.
    if open_bins_count > 5 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // New bin logic:
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    // Only pick a new bin if the current best existing bin is extremely poor.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin
        score = 65.0;

        // If we are near the end of the stream, prioritize using existing bins
        score += progress * 40.0;

        // If we have very few open bins, opening a new one is less penalized
        if open_bins_count < 2 {
            score -= 10.0;
        }
    } else {
        // If this is the last fitting bin, prioritize it to avoid forced new bin
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Calibration against mean_residual: favor bins that are closer to the global average
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

