    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - progress);
    }

    // 4. Global State Awareness: If we are near the end of the stream, 
    // prioritize filling existing bins over opening new ones.
    if fitting_bins_count == 0 {
        // This is a new bin candidate. 
        // Only pick if we really have no other choice, or if we are early in the stream.
        score += 50.0 * (1.0 - progress);
    } else {
        // If this is the last chance for this item (fitting_bins_count == 1), 
        // reward using the existing bin to avoid opening a new one.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 30.0;
        }
    }

    // 5. Mean Residual Coupling: If the current bin is significantly emptier than the average,
    // prioritize using it to normalize bin state.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let usage = (bin_capacity - bin_residual) as f64;
    let mut score = post_residual as f64;

    // 1. Refined Fragmentation Suppression: Targeting dead space slivers
    if post_residual > 0 {
        if post_residual < 7 {
            score += 140.0 / (post_residual as f64 + 0.15);
        } else if post_residual < 15 {
            score += 52.0;
        }
    }

    // 2. Predictive Lookahead: Non-linear coupling for next item fit
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 95.0;
        } else if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 42.0;
        } else {
            let space_after_next = post_residual - next_item_size;
            score -= (30.0 - space_after_next as f64).max(0.0) * 2.2;
        }
    }

    // 3. Adaptive New Bin Threshold: Dynamic penalty based on global packing state
    if is_new_bin {
        let open_cost = 145.0 + (mean_residual * 3.2) + (progress * 620.0) + (open_bins_count as f64 * 1.5);
        score += open_cost;
    } else {
        // 4. Load Balancing: Enhanced variance minimization
        let deviation = (usage - (bin_capacity as f64 - mean_residual)).abs();
        score += deviation.powf(1.75) * 1.1;
    }

    // 5. Scarcity Logic: Consolidation pressure
    if fitting_bins_count > 0 {
        score -= 230.0 / (fitting_bins_count as f64 + 0.5).sqrt();
    }

    // 6. Tail-End Compaction: Aggressive closure with tighter slope
    if progress > 0.85 {
        if is_new_bin {
            score += 4200.0 * (1.1 + progress);
        } else {
            score -= usage * 11.0;
        }
    }

    // 7. Residual Quantization: Favoring power-of-two or decadic alignment
    if post_residual == 0 {
        score -= 55.0;
    } else if post_residual % 5 == 0 {
        score -= 15.0;
    }

    // 8. Density-Fit Coupling: Non-linear reward for high-density bins
    let density = usage / bin_capacity as f64;
    if !is_new_bin {
        score -= density.powf(1.5) * 65.0;
    }

    // 9. Entropy reduction: Penalize density-divergent bins relative to local mean
    if !is_new_bin && post_residual as f64 > (mean_residual * 2.4) {
        score += 85.0;
    }

    // 10. Global Density Incentive: Dynamic thresholding for capacity utilization
    if open_bins_count > 5 {
        score -= (bin_capacity - post_residual) as f64 * 1.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle).
    // We want to minimize post_residual, so low post_residual is good.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, the cost of opening a new bin should be balanced 
    // against the efficiency of filling existing bins.
    if is_new_bin {
        // High penalty for new bin early in the stream, decreasing as we approach the end.
        // This encourages aggressive packing early.
        score += 80.0 * (1.0 - progress).powf(0.5);
    } else {
        // If it's an existing bin, favor placements that keep the bin residual 
        // close to the mean_residual of other bins to maintain uniformity.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.2;

        // Lookahead heuristic: If the next item can fit in the current post_residual, 
        // prioritize this bin. If the next item is large (e.g. > 50), penalize 
        // small post_residuals that would strand the large item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0; // Reward bin that can accommodate the next item
            } else if next_item_size > post_residual && post_residual < 20 {
                score += 25.0; // Penalize creating "dead space" too small for next item
            }
        }
    }

    // Adjust for fitting_bins_count:
    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessarily opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Refined Fragmentation Penalty: Target specific high-waste slivers with non-linear scaling
    if post_residual > 0 && post_residual < 16 {
        let severity = if post_residual < 6 { 75.0 } else { 35.0 };
        score += (20.0 - post_residual as f64).powf(1.2) * (severity + progress * 40.0);
    }

    // 2. Lookahead Synergy: Anticipatory Fit with localized optimization
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 92.0; 
        } else if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 32.0 * (1.0 + progress);
        } else {
            // Reward "perfect" fit potential for the next item
            let headroom = post_residual as f64 - next_item_size as f64;
            score -= (25.0 - headroom).max(0.0) * 2.5;
        }
    }

    // 3. Adaptive New Bin Threshold: Dynamic cost adjustment
    if is_new_bin {
        let open_cost = 142.0 + (mean_residual * 2.6) + (progress * 520.0);
        score += open_cost;
    } else {
        // 4. Load Balancing: Variance minimization with capacity-relative normalization
        let usage = (bin_capacity - bin_residual) as f64;
        let deviation = (usage - (bin_capacity as f64 - mean_residual)).abs();
        score += deviation.powf(1.6) * 1.8;
    }

    // 5. Scarcity Logic: Consolidation pressure
    if fitting_bins_count > 0 {
        score -= 225.0 / (fitting_bins_count as f64 + 0.2).sqrt();
    }

    // 6. Tail-End Compaction: Aggressive closure at late stages
    if progress > 0.80 {
        if is_new_bin {
            score += 3200.0 * (1.0 + progress);
        } else {
            score -= (bin_capacity - bin_residual) as f64 * 7.5;
        }
    }

    // 7. Residual Quantization: Favor "clean" remainder space
    if post_residual == 0 {
        score -= 52.0;
    } else if post_residual % 5 == 0 {
        score -= 22.0;
    }

    // 8. Density-Fit coupling: Bias towards filling deep bins
    if !is_new_bin {
        let depth = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= depth * 45.0;
    }

    // 9. Micro-sliver avoidance: Harsher penalty for near-empty bins
    if post_residual > 0 && post_residual < 5 {
        score += 105.0;
    }

    // 10. Entropy reduction: Penalize bins that create large variance in residual distribution
    if !is_new_bin && post_residual as f64 > (mean_residual * 2.0) {
        score += 85.0;
    }

    // 11. Global Density Incentive: Heavier penalty for opening too many bins
    if open_bins_count > 7 {
        score -= (bin_capacity - post_residual) as f64 * 1.3;
    }

    score
}
